window.PB_TEXTS=window.PB_TEXTS||{};window.PB_TEXTS["PB-652C611D0207B6F5"]={"schemaVersion": 1, "documentId": "PB-652C611D0207B6F5", "title": "Hallman: Finkels Parentations-Act (1777)", "sourceSha256": "652c611d0207b6f533498232f2dc0f42fe06476ec808735c5ea84f43ae9ad642", "method": "Poppler pdftotext -layout; existing PDF text layer; no new OCR", "extractedAt": "2026-10-05T13:28:08.971655+00:00", "pages": [{"pdfPage": 1, "printedPage": null, "text": "FINKELS\nPARENTATIONS-ACT\n\n            Carl Israel Hallman\n\n\n\n                        Tryckår 1777\n\n\n\n\n                   www.dramawebben.se\n\n\n\n\n  http://creativecommons.org/publicdomain/zero/1.0/deed.sv"}, {"pdfPage": 2, "printedPage": null, "text": "№1 Wärdinnan på Latinska Klubben, Fru Cicilia~\n№2 afskedade Fält Commissarien Drommelberg ~\n№3 En Hökare №4 Proviant Skrifvaren Söderlank~\n№5 Badaren Fussvassers Hatt~"}, {"pdfPage": 3, "printedPage": null, "text": "", "ocrText": "", "ocrSegments": [""], "autoTextLayer": "original", "machineAssessment": {"confidence": 0.0, "needsReview": true, "automaticSplit": false, "engine": "Tesseract 5.5.3; LSTM; psm 3", "version": "batch-v2", "sourceSha256": "652c611d0207b6f533498232f2dc0f42fe06476ec808735c5ea84f43ae9ad642", "modelHashes": {"Fraktur": "29a867a25f1b00a5e9827356582515619d5102688bc1d14015789c78941116ee", "swe": "360303308aa5d4a912ac3b3637691152b7532d9bd6e960639db1affb83db7ea9"}, "languages": ["swe"], "selection": "confidence-and-coverage-heuristic; not proofreading", "createdAt": "2026-10-05T14:59:10.068765+00:00", "statisticsParser": "tsv-quote-none-v1; prior row counts checked"}}, {"pdfPage": 4, "printedPage": null, "text": "Öhl Sällskapet.\n\nGraverad på Öhl.Oratorernes Omkostnad Finnes Til\nSalu för den mästbiudande på Smedgatan uti huset\n               Försilfrade Melon №128."}, {"pdfPage": 5, "printedPage": null, "text": "Finkels\nPARENTATIONS-ACT.\n\n              Prologue\n                 Til\n           Comedien,\n               Kallad\n\n\n\n Det Underjordiska Bränwins-\n          Bränneriet.\n\n\n\n            Stockholm,\n    Tryckt hos Carl Stolpe, 1777."}, {"pdfPage": 6, "printedPage": null, "text": "Personerne.\n\n          Fru Cicilia.       Wårdinnan på Latinska Klubben.\n          Madam Barbro.      Krögerskan på Krypin.\n          Ingrid.            Cicilias Piga.\n          Drommelberg.        En afskedad Fält-Commissarins.\n\n\n\n\n          {\n          Fusswasser.        En Badare.\n          Et Håf-Råd.\nKlubb-    Långa Referendarien\nHerrar.   Buttelbirius.       En Magister.\n          Söderlank.          En Prowiant-skrifware.\n          En Sökare.\n          Secter Gasp.         En ung näswis Auscultant.\n\n\n          Scenen är på Latinska Klubben."}, {"pdfPage": 7, "printedPage": null, "text": "Scene. I.\n\nFru Cicilia, sittjande i en Länstol och spinner med glasögon.\nHennes Piga, et stycke därifrån och kardar.\n\n                                  Cicilia.\n     Ingri, du må tro jag hade en hederlig Man, from och\ngod war han som en Ängel, han kunde krypa under\nmina fötter, fast han gick med Lockperuque, bruna\nKläder och en liten nätt Silfwer spatserswärja, som satt\nut genom Råckrynkan.\n                                  Ingrid.\n     Hwad hade då kära Fruns salig kära Man för tjänst?\n                                  Cicilia.\n     Jo du må tro han hade en hederlig tjänst, han war\nLiqvidations-Commissarius wid sista Finska Kriget: han\nwar så from och enfalldig west du, at när han fick et Stop\nÖl ock några Pipor Tobak in til sig i sin lilla Kammare,\nså satt han och räkna och skref hela eftermiddagarne.\n                                  Ingrid.\n     Nå jag kan säga: Men hwad hette då salig Herrn?\n                                  Cicilia.\n    Jo han hade et stolt namn: Han hette Birger Ce-\ndermes.\n                                  Ingrid.\n     Ha! hi, hi, hi! Birger Cedermes, Birger Cedermes.\n                                                                Cicilia.\n\n\n\n\n                                     A2"}, {"pdfPage": 8, "printedPage": null, "text": "4\n\n                             Cicilia.\n     Hwarföre skrattar du?\n                             Ingrid.\n    Jo därföre at det war så stolt; men hwad gjorde kära\nFrun då, när salig Herrn war så flitig.\n                             Cicilia.\n     Hwad jag gjorde, jo, jag hade nog at göra jag, det\nomgicks mycket hederligt folk i wårt hus, Officerare, Bor-\ngare, Skrifware, til och med Prester.\n                             Ingrid.\n     Til och med Prester: nå jag tilstår; men hwad hade\nkära Frun at göra med alla de där Karana, eller huru\nhant salig Herrn, at göra sina syslor för så mycke främ-\nmande.\n                             Cicilia.\n      Salig Herrn: ditt nöt, har jag icke sagt, at han satt\ni sin kammare och skref och räkna, du må tro det kunde\nnog sätta honom göra det.\n                             Ingrid.\n     Ja, ja, jag kom intet ihog det jag. Men gick intet sa-\nlig Herrn ut ibland och hälsa på dåm också.\n                             Cicilia.\n     Nej, därföre fick salig Herrn Öl och Tobak, på det han\nskulle hålla sig inne i sin Kammare, och när jag wille wara\naldeles säker för honom, så gaf jag honom en god sup\nibland.\n                                                         Ing-"}, {"pdfPage": 9, "printedPage": null, "text": "5\n\n                             Ingrid.\n     Ja, ha, ha, hi, hi, det war knepet det, genom Brän-\nwin tror jag man kan winna all ting i werlden; jag har\nockså wunnit någon ting genom Bränwin.\n                             Cicilia.\n     Hwad har du då wunnit?\n                            Ingrid gråter och kardar.\n                             Cicilia.\n   Är det så farligt, kan du intet säga hwad du har\nwunnit?\n                             Ingrid.\n    Jo, jag skal säga kära Frun, om kära Frun lofwar\nmig at tiga.\n                             Cicilia.\n     Hå ditt Fjoll, nog wet du at jag tiger.\n                             Ingrid.\n     Jo, kan kära Frun tro, jag tjänte hos en Bryggare\nför Piga i Brännhuset.\n                             Cicilia.\n     Ja nog kan jag tro det, nå än sen då?\n                             Ingrid.\n      Jo å så råka jag då och då at tappa lite Bränwin uti\nen liten Qwarters Bouteill, och stack åt honom i mjugg.\n                             Cicilia.\n   Nå! — — — — men ännu har jag inte hört hwad du har\nwunnit genom Bränwin.\n                                                         Ing-\n\n\n\n\n                                    A3"}, {"pdfPage": 10, "printedPage": null, "text": "6\n\n                            Ingrid.\n    Jo, jo men kära Fru, jag want med den där unga\nSjöman (gråter.)\n                            Cicilia.\n    Hwad då.\n                            Ingrid.\n    I tacksamhet, en liten Son; men han war ganska liten.\n                            Cicilia.\n      Ja, ja, jag kan wäl tänka han war i proportion efter\nden lilla Qwarters Bouteillen — — — — — men Ingrid! jag ha-\nde aldrig kunnat trodt dig därom, du är intet mer än 21\når och har fått en Son, och jag som war gift i 30 år har\nfått ingen med salig Cedermes.\n                            Ingrid.\n      Ja, lik wuli kan dä wara med hwem man får, men\nkära Fru det är icke alla, som winna et och dä samma\ngenom Bränwin; somliga winna Pengar och stora Hus, som-\nliga stora Karitörer, somliga si och somliga så: jag undrar\nhwem dä ä som inte wil befatta sej med Bränwin och win-\nna däruppå, alt ifrån Adelsman til Bonden, dä ä en fly\nwara dä kära Fru och föder många frugter.\n                            Cicilla.\n     Ja du har rätt nog, Ingrid: dä föder wist många\nfrugter, men hos mig har dä inte stort födt.\n                            Ingrid.\n     Nå bewars, kära Fru, har dä inte födt hos Er, så\nwet jag inte: stora Silfwerbägare, Silfwerskålar, Tumlare,\nCaffekanna, Mjölkskål, är dät war dä?\n                                                        Cicilia."}, {"pdfPage": 11, "printedPage": null, "text": "7\n\n                           Cicilia.\n    Å, det är mäst samlat af hembrygt Öl, det minsta af\nBränwin.\n                           Ingrid.\n     Men, söta Fru, när jag skulle komma hit til Frun i\ntjänst, så war dä några, som skratta åt mej, för dä jag\nskulle komma te tjäna på Latinska Klubben. Hwarföre kal-\nlas Fruns Hus så?\n                           Cicilia.\n      Det är ingen skam i den Titeln må du tro; jo, jag\nkan nog säga dig hwarför han så kallas. Salig Cedermes\ntalte Latin så fort som Hästen trafwar, derföre samlade han\nock många Latinska Böcker; efter hans död kom jag at\nflytta ut de der Böckerna, och satte dem på en Hylla i\nBrygghuset, då hände sig en gång, när jag hölt på at bryg-\nga, at medan jag war ute, en utaf Böckerna kom at ram-\nla ner i Bryggkaret; jag wiste åf ingen ting, Färsk-öls Ka-\nret geck åt på en afton, och då en utaf Gästerna, jag kan\nwäl säga hwem det war, oss imellan sagt, det war Fält-\nCommissarien Bror Drommelberg, skulle öpna sitt Stop och\ndricka, hwilket skedde med någon force, ty han war torstig\nutaf en Lax-wälling, som han åt hos mig om middagen,\nlät se, det war på en Torsdag, om jag mins rätt, ja,\nja det war på en Torsdag, jag mins ändå at wi åt Årter\nom Onsdagen, som jag aldrig plär göra; men jag wille\npröfwa de der Årterna, som jag fick skickande från Sörman-\nland utaf Fogden på Hesselby, som är gift med min Syster-\nDotter, och har Barn, redan stora som jag; den äldsta utaf\ndem, wet du, ska gifta sig innan kort med Cappelans\nSon, som är Klockare och Organist i Församlingen. Nå det\nwar godt och wäl: så wet du när Drommelberg skulle öpna\n                                                     Stopet,"}, {"pdfPage": 12, "printedPage": null, "text": "8\n\nStopet, så stötte honom en Bok på Näsan, han blef flak,\ntog opp Boken ur Stopet och såg i honom och sa at det war\nen Latinsk Bok, som hette Cornelius Nepus; hela Laget\nskrattade öfwerljudt åt denna händelse, och ifrån den stun-\nden har mitt Hus fått namn af Latinska Klubben. Dess\nutom går här ock en hop lärdt Folk, som roa sig med at\ntala Latin, sedan de ha druckit några Stop. Men det klap-\npar på dörren, gå, se åt hwem det är.\n\n\n                           Scene. II.\n\n               Madam Barbro. Fru Cicilia, och Ingrid.\n\n                      Mad. Barbro niger.\n     God dag, kära Fru, förlåt mig, jag kommer så\ndristigt.\n                             Cicilia.\n     Å det skadar inte, Madam Barbro, wälkommen, war\nså god och sitt ner: hur står det til i edra Gårdar?\n                        Mad. Barbro.\n     Å, kära Fru, hur ska det stå til i dessa swåra tider,\njag går som jag skulle gå genom jorden, alt ting bär emot,\net ondt föder et annat: jag beklagar wåra Barn och Efter-\nkommande, dä ä wist dä.\n                             Cicilia.\n     Ja, nog ä tiderna swåra; men Ni ser så bedröfwad\nut, har någon olycka händt Er?\n                        Mad. Barbro.\n    Ja, ja men, ty wärr, jag har just råkat i samwets-\nqwal.\n                                                         Cicilia."}, {"pdfPage": 13, "printedPage": null, "text": "9\n\n                            Cicilia.\n    Å stackars Gumma jag beklagar. Men hwad har wäl\ndå händt? Har några tjufwar stulit hos Er.\n                         Mad. Barbro.\n    Nej just inte då.\n                            Cicilia.\n    Kanske den der andra saken, Ni wet, har blifwit uptåckt?\n                         Mad. Barbro.\n    Nej, men, då fruktar jag wäl inte före.\n                            Cicilia.\n    Är Er Man död då?\n                         Mad. Barbro.\n    Nej men, som wärre är: nog lefwer den fyll-pråmen.\n                            Cicilia.\n    Nå så säg mig då; ja spricker eljest af nyfik enhet.\n                         Mad. Barbro.\n    Kände kära Frun, Finkel?\n                            Cicilia.\n     Jo, lät se, — — — Finkel — — — Finkel — — — jo, jag tror\nwäl, jag känner honom; hå, han går ju altid i en lång\nröd Surtout.\n                         Mad. Barbro.\n    Ja, ja, då war så.\n                            Cicilia.\n    Han brukar ju altid stöflor, om jag mins rätt, och\nRosett Peruque.\n                                                           Mad.\n\n\n\n\n                                     B"}, {"pdfPage": 14, "printedPage": null, "text": "10\n\n                           Mad. Barbro.\n     Ja, ä ja, aldeles riktigt.\n                                  Ingrid.\n     Å gustre, kära Fru, dä måtte då wisserligen wara\nden der med stora wackra röda näsan; eljest en liten spän-\nslig Herre til wäxten.\n                           Mad. Barbro.\n     Ja, ja.\n                                  Cicilia.\n     Ja, då wet jag hwem det är: han är Avocat; det\nwar han som förde ut Processen för Fiskblötar Mor, emot\nSeeter Gasp: han har warit hos mig några gånger, fast\ninte nu på lång tid.\n                           Mad. Barbro.\n    Nej, nej, kan wäl wara: han geck mäst på Smedgats\nklubben.\n                                  Ingrid.\n    Ja, jag känner honom ock ganska wäl, när jag påmin-\nner mej. Han brukade mäst Carpus: jag hade så när\nkommit i tjänst hos honom för et par år sedan.\n                                  Cicilia.\n     Nu kommer jag också ihog, när jag såg honom första\ngången: han hade råkat at falla i kull på lilla Glasbruks-\ngatan utan för Struf-bagarns: där låg han stackare öfwer\nen Hörnsten, och Armarna hängde ner i en wattnpuss, Car-\npusen låg et stycke ifrån honom, tillika med ena halfärmen;\nalt det der tog jag opp, och stoppade i hans ficka och geck\nmin wäg: Hjertat blödde just i mig at se honom wara så\n                                                      sjuk;"}, {"pdfPage": 15, "printedPage": null, "text": "11\n\nsjuk; det är underligt ofta med wåra bästa Karlar, de tåla\ninte stort förrän de bli fotfallna.\n                         Mad. Barbro.\n     Ja, ja, dä är sant nog dä, de ä oftast swagare än wi.\n                             Cicilia.\n    Hör, Madam Barbro, det berättades, at den der\nFinkel, skulle gifta sig med Fiskblötar Mor, är det sant dä?\n                         Mad. Barbro.\n     Ja, nog tror jag de hade godt öga til hwaran; men\ndä blef ändå inte af.\n                             Cicilia.\n     Jo, jo, jag wet, at han skänkte henne en swart Siden\nHufwa med stjert uppå; han köpte ändå Sidentyget utaf\nen Danzigerska, som plär gå til mig, och gaf 12 Daler\nAlnen for det; och kan Ni tro Madam Barbro, at det\nwar mycket bättre, än det jag har i min Salopp. Ingrid,\nhör Ingrid, spring in efter min Salopp, som hänger in-\nne i bruna hörnskåpet, Nyckelknippan ligger på Tafletten.\n      Ingrid går.\n                         Mad. Barbro.\n    Ju mera kära Frun talar om Finkel, ju mera öks\nmin sorg och min ängslan.\n                             Cicilia.\n     Hwad har Ni då för oro öfwer honom? kanske han\nhar warit något närgången? sådan swaghet faller ofta på\nAvocater och qwicka genier: sådant bör man förlåta honom.\n                         Mad. Barbro.\n     Å ja, nog förlåter jag sådant lappri: aldrig oroas\njag deröfwer; men dä ä wäl dä som wärre ä.\n                                                          Cicilia.\n\n\n\n\n                                     B2"}, {"pdfPage": 16, "printedPage": null, "text": "12\n\n                             Cicilia.\n     Hwad kan wäl det wara, Ni förskräcker mig just.\n                         Mad. Barbro.\n     Jo, medan pigan ä ute, skal jag förtro Frun.\n                             Cicilia.\n     Hwad då?\n                         Mad. Barbro.\n     Han är nu död.\n                             Cicilia.\n    Hwad! är han död? nå, nå, frögda själen. Men\nhwad behöfwer Ni så mycket oroas deröfwer.\n                         Mad. Barbro.\n     Jo, ty han har dödt genom mitt förwållande.\n                             Cicilia.\n    Har Ni då råkat at slå ihjäl honom, i wåda kan jag\ntänka.\n                         Mad. Barbro.\n     Nej inte jag, utan Bränwins-förbudet har förord-\nsakat denna olyckan.\n                             Cicilia.\n     Nå, hwad behöfwer Ni då ängslas deröfwer?\n                         Mad. Barbro.\n    Jo, för ty, jag ändå på wist sätt är ordsaken til\nhans död.\n                             Cicilia.\n     Jag begriper Er intet, säg då på hwad sätt.\n                         Mad. Barbro.\n     Genom min Laglydighet.\n                                                        Cicilia."}, {"pdfPage": 17, "printedPage": null, "text": "13\n\n                               Cicilia.\n     Jag ber Er för all ting, uplys mig denna Gåtan,\njag är helt förwånad. (Ingrid kommer in med Saloppen).\nNå du är god, at skicka efter döden, lägg Galoppen här\noch gå ut igen, se efter om Karet gäser bra, hölg wäl\nöfweret. (Ingrid går.)\n                          Cicilia. (ropar.)\n    Ingri! ä Stopena wäl twättade? rättnu kommer\nHerrarna.\n                               Jngrid.\n    Ja kära Fru (går.)\n                               Cicilia.\n    Ingri! gå ner i Källarn och tag opp et fat Byckling;\nHerrarna knapra så gärna Byckling under et Stop Öl.\n                               Jngrid.\n    Ja, ja, kära Fru (går.)\n                               Cicilia.\n      Ingri, hör Ingri, så mycket du wet, ska du altid\nsätta fram Porcellains talrik åt långa Referendarien; ty\nhan är wan, at lefwa bland de förnäma, och är mycket\ncuriöse. Han har också en Mamselle hos sig, som han\ntalar om alt ting före.\n                               Ingrid.\n    Ja, ja, kära Fru. (går.)\n                               Cicilia.\n    Ingri!\n                               Jngrid.\n    Å ja, då, kära Fru.\n                                                       Cicilia.\n\n\n\n\n                                     B3"}, {"pdfPage": 18, "printedPage": null, "text": "14\n\n                                  Cicilia.\n     Ska du säja, .å ja då, åt din Matmor, din slinka.\nSpring straxt bort til Hökars, och köp mig hem et Skål-\npund Tallstrunt.\n                                  Ingrid.\n      Ja, ja kära Fru. (går.)\n                                  Cicilia.\n   Hör Ingrid ta in Bränwins-flaskan först och lilla\nTumlarn.\n                         (Ingrid går ut men kommer straxt in.)\n                             Cicilia (slår uti.)\n      Skål Madam Barbro.\nMad. Barbro (stiger up och niger.) (Cicilia slår i Bränwin åt henne.)\n\n                         Mad. Barbro (super.)\n     Jag har den äran at dricka gunstiga Fru Commisa-\nriuskans skål.\n                                  Cicilia.\n    Sitt nu ner och säg mig ordsaken til Er sorg öfwer\nFinkel.\n                             Mad. Barbro.\n      Dagen efter Bränwins-förbodet helt bittida om mor-\ngonen, kom Finkel til mig uttorstig, näsan på honom war\nblå, som en Kittelbotten, läpparna woro helt bleka, han\ndarrade som et Aspelöf, så det gjorde mig rätt ondt, at\nse denne usle kroppen; alt på honom, som synbart war, för-\nkunnade ängslan och förskräckelse. Ge mig en sup, sade\nhan med en skälfwande ton, föll baklänges på en bänk och\nstånkade grufweligen, men Frun wet sjelf, hwad olägenhet\njag hade kunnat haft, om jag gifwit honom Bränwin,\n                                                                   man"}, {"pdfPage": 19, "printedPage": null, "text": "15\n\nman kan intet se folk längre än til tänderna, han hade\nkunnat gifwit mig an, och sedermera supit på min plikt-\nsumma en god tid Tro mig, han hade kunna fått många\nwackra supar för 300: de Daler. Nej, nej, Barbro har förr\nen gång warit ute för smäln, jag har lärt mig at blifwa för-\nsigtig, med et ord, jag gaf honom intet något Bränwin;\ndå blef Karlen desperat, tog hund och katt til wittne, at\njag war saker til hans död, tumlade ner på golfwet med\nsin röda Surtout, och efter et matt afskedstagande af\nwerlden, upgaf sin Anda mitt under min Näsa.\n                 Cicilia (slår ihop händerna och springer up af stolen.)\n    Förskräckeligt, förskräckeligt! hade Ni då intet Brän-\nwin Madam Barbro.\n                         Mad. Barbro.\n     Jo, dä wa så likt dä, kära Fru. Barbro skulle wara\nutan Bränwin! nog hade jag Bränwin fullt opp, fast det\nwar förbudit; men skulle jag ge Bränwin i förbudna tiden,\nåt en Advocat så slug som Finkel, en Karl, som kunde be-\nwisa det allraorimmeligaste, än mer dä som sanning war,\nnej fäll wiste jag bättre.\n                              Cicilia.\n     Ni är då ordsaken til denna arma Karlens död! ack! jag\nskulle haft samwete, at neka honom. Men de här Krögerskorna,\nde här Krögorskorna, de ä hårda som bärg, grofwa själar—kan\ntäncka —hör Madam Barbro, förut har jag haft någon aktning\nför Er, men sedan jag fådt weta hela denna Er misshandel\nmed Finkel, så måtte jag säga, at Ert ansigte fått i mina\nögon et helt annat utseende; farwäl, farwäl — men apro-\npos, när Ni såg honom ligga i själtåget, doppade Ni då\nintet åtminstone en fjäder i Bränwin och strök på hans\ndöende läppar, kanske han hade kommit til lifs igen.\n                                                             Mad."}, {"pdfPage": 20, "printedPage": null, "text": "16\n\n                           Mad. Barbro.\n     Nej, min sann gjorde jag intet, jag såg han ändå\nskulle dö, och då hade jag icke haft någon ersättning der-\nföre, så framt jag icke welat gå in med i Concursen, och\ndå har det dragit långt ut på tiden med betalningen.\n                                Cicilia.\n     Ack! hwad Ni är oförskämd — — gå Er wäg.\n                           Mad. Barbro.\n     Ja, sådant måtte jag lida för min Laglydighet skuld.\n                                Cicilia.\n     Skyll på din Laglydighet! din stygga, — — skyll snarare\npå ditt gemena, hårda och nedriga sinne, gå din wäg, sä-\nger jag.\n               (I det Madam Barbro skal gå ut, möter henne Finkel i\n         Spökelse gestalt, sattar henne i armen och nyper henne: hon\n         skriker.)\n      Ack! nådige Herr Secreter, om Ni kan supa Bränwin,\neller om Ni behöfwer något Bränwin i det andra lifwet,\nså kom til mig i natt kl. mellan 12 och Ett, så skal en\nhel Kanna Brännwin stå til reds åt Er i Farstun.\n               (Under detta faller Fru Cicilia af förskräckelse ifrän stolen;\n         Finkel rister Barbro och wil dra henne med sig, hon stretar\n         emot och hukar sig ned.)\n     Ach min Gunstiga Herr General Abbecat, om Ni wil\nlåta mig ännu en liten tid wara i werlden, så skal jag til\närkänsla taga Fiskblötar Mor i mitt hus, och låta henne\nfödas til dödar.\n               (Finkel tar henne i Näsan och wrider, omsider släpper han\n         henne och skrider baklänges ut. Barbro står en stund hukan-\n         de och darrar, springer sedan ut på andra sidan af Theatren.)\n\n                                                                   Cicilia."}, {"pdfPage": 21, "printedPage": null, "text": "17\n\n               Cicilia (ligger qwar på golfwet och ropar, med en af för-\n         skräckelse hes röst.)\n     Ingril — — — Ingri! — — — Ingri! — — — Ingri! — — —\nIngri! — — —\n\n\n                                 Scene III.\n\n               Ingrid (kommer in springandes)\n      Ach! hwarföre ligger kära Frun på golfwet, får jag\nlof at springa in efter en kudda och lägga under hufwudet?\n                                  Cicilia.\n    Ditt gemena stycke, hwarföre dröjer du så länge? kom\noch hjelp op mig! är han borta än?\n               Ingrid (tar Cicilia under armarna och lyfter henne op.)\n     Ja han gick nu nyss ut genom porten.\n                                  Cicilia.\n   Hwad! — — — gick han ut genom porten, som en annan\nmenniska?\n                                  Ingrid.\n    Ja, han skulle wäl det, wet jag, han kunde ju intet klif-\nwa öfwer planket.\n                                  Cicilia.\n    Menar du at fan behöfwer gå genom portar eller klif-\nwa öfwer plank.\n                                  Ingrid.\n     Nej, han är ingen fan, han är en ärlig Gässe, jag\nhar warit förlofwad med honom i tu år, han gjorde nu\nbara en liten kort visit hos mig för första gången, och\nskänkte mig en Citron.\n                                                                Cicilia.\n\n\n\n\n                                         C"}, {"pdfPage": 22, "printedPage": null, "text": "18\n\n                            Cicilia.\n     Ach! hwad säger du? tar du Citroner af fan din ogu-\ndaktiga kona?\n                            Ingrid.\n    Hå kära Fru, wi bedref ingen ogudagtighet: han\nskänkte mig bara en liten Citron, hwad war det mer?\noch om jag änteligen skal skrifta mej, så kyste han mej\nganska lite på nedra läppen, och klappa mej bara si så här:\ndä war inte ondt i det.\n                            Cicilia.\n     Låter du spöke klappa och kyssa dej ditt troll?\n                            Ingrid.\n      Nej, han är inte något spöke, för spöke har ingen kropp,\nfast det ser så ut; men min Musiö Michel har Kropp, dä\nmåtte jag wäl weta.\n                            Cicilia.\n    Din Elemenskade Slyna, spring straxt in i min Säng-\nkammare och tag hit struten, som ligger på tafletten med\nrökpulfwer uti, at röka bort det onda tyget.\n                            Ingrid.\n     Jag kan wäl säga det behöfs ingen rökelse efter min\nfästman Musiö Michel, ty han är en snygger Karl, och dess-\nutom war han bara hos mig i Köket, så dä inte kunde\nkomma någon lukt hit in.\n                            Cicilia.\n     Hwad är det för en Musiö Michel du talar om.\n                            Ingrid.\n    Jo, dä ä den Sjöman, som jag blef bekant med hos\nBryggars.\n                                                       Cicilia."}, {"pdfPage": 23, "printedPage": null, "text": "19\n\n                               Cicilia.\n     Och, med hwilken du want en liten Son för Bränwin.\n                               Ingrid.\n     Ja — — så wida han war min Fästman.\n                               Cicilia.\n     Så wida han är din Fästman, så torde du wäl också\nnu wilja winna en Dotter för mitt Färsköl; men jag skal\nlära dig ditt lättfärdiga stycke, at ha Båtsmansslokar hos\ndej, när hin håles spökelser grassera hos mej.\n                               Ingrid.\n     Hå kära Fru! inte är jag Jaloux på Frun , hwarföre\nskal Frun wara Jaloux på mej, hwar och en Ålder har\nsina wänner och sitt sällskap.\n                               Cicilia.\n    Nå jag skal också ärligt smörja dej din näspärla för\nsådana infall.\n               (Springer efter en Karbas och börjar slå henne, Ingrid\n                 skriker.)\n\n\n\n                             Scene. IV.\n\n                  Badaren Fusswasser.. Cicilia. Ingrid.\n\n                             Fusswasser.\n    Hwass henker! hwarfor schall man prikle ten junge\nwachre Jungfer?\n                               Cicilia.\n     För det hon är lättfärdig och näswis.\n                             Fusswasser.\n     Lächtfärtich — — — — wass will dass sagen?\n                                                                Cicilia.\n\n\n\n\n                                        C2"}, {"pdfPage": 24, "printedPage": null, "text": "20\n\n                             Cicilia.\n     Det wil säga, at hon har sina slångkar hos sej, när\nhin håles spökelser komma in til mej.\n                          Fusswasser.\n      Hwat sejen sie? hatt schpikelser wart hir? dass ist un-\ntrulich.\n                             Cicilia.\n     Jo men: Finkel war här nyss.\n                          Fusswasser.\n     Hwas! ten tete Finkel? — — — ten Affecat, ten Secre-\nterer?\n                             Cicilia.\n     Ja just han sjelf med egen röd näsa.\n                          Fusswasser.\n     Dass ist nicht möklik, han er ju räcktschaffens ted, jach\nhar ju man läst darum in Tachlig Allehante.\n                             Cicilia.\n    Han må wara död eller lefwande, så war han här och\nklämde Barbro på Krypin, som nu nyss war hos mej.\n                          Fusswasser.\n     Dass ist lauter schnak; hun muss sich aderlaten, late\nClistir sätten, undt gute öppning krigen; darnach praff\nlaxiren, weiter praff schwitzen, undt zum guten letzt, en\nguten Mag-Elixir nehmen.\n                             Cicilia.\n     Herre disputera mej inte! han war här säjer jag, så\nwist som jag är en Ärlig Menniska.\n                          Fusswasser.\n     Ach nein, mein Frau, ach nein, dass muss ich ferstehen.\n                                                           Cicilia."}, {"pdfPage": 25, "printedPage": null, "text": "21\n\n                               Cicilia.\n     Å hwad förstå Ni? Ni är ju bara en badare.\n                       Fusswasser (blir ond.)\n     En Patere — — — en Patere — — — wass sagen sie? en\nPatere, ja ich bin ein Patere, undt tach mich knäffel ten\nfornämst in mein prufessiun: gibt mir man hit Pleck undt\nFäder, so schall jach man ein Recept schriwen, dat die\nSchpickelse schall fare aus den koppf, durch ten finster\nhiraus.\n                                Cicilia\n     Jag wil sätta opp alt mitt Silfwer i wad, at det\när sant hwad jag har sagt.\n                             Fusswasser\n     Nein, nein, nein, gute Frau, dass komt fon die un-\nde samfett, oder fon ein inpiltung, oder fon ein dicke blud,\ndass muss ich weisen, sum hatt so mange hundert menschen\nBarbiret, Kopfet, Aderlasset, Clistiriret undt Curiret for\nhundert sinom dausen krankheiten.\n                               Cicilia.\n     Ach! Ni är en stor Narr.\n                             Fusswasser\n    Ich bin kein narr. Ha, ha, ha, dise alte Frauenen-\nzimmer! dise alte Frauenzimmer!\n                               Cicilia.\n     Wil Ni göra mig halt också?\n                             Fusswasser\n     Ach kein reson, kein reson. Ingri lill! gibt mir ein\nhalb schtuff Bier, dass ist viel besser.\n               (Fru Cicilia går i sin Sängkammare: Ingrid kommer in\n          med et Trädstop Dricka. Badaren sätter sig ner wid bordet.)\n\n                                                               Scene\n\n\n\n\n                                        C3"}, {"pdfPage": 26, "printedPage": null, "text": "22\n\n\n\n                               Scene.V.\n\n           Långa Referendarien, Badaren, Ingrid, så snart hon får\n                 se Referendarien, springer ut efter en Porcellains Talrik och\n                 sätter för honom.\n\n                          Referendarien.\n     Hwad skal jag med Porcellains Talriken, Ingrid lilla?\n                                Ingrid.\n     Jo, för dä Herrn umgås med de förnäma.\n                          Referendarien.\n       Ja, dä wäl dä, men nu gör jag intet med någon\nPorcellains Talrik; gif mig häldre et Stop Öl. (han sät-\nter sig wid bordet) Si guten abend, guten abend mein Herr\nFusswasser, wie stets und wie gets.\n                              Fusswasser.\n     Hå, ich danke, ich danke mein Herr Referentarius,\ndass steht wohl mit mir, aber wie stets mit mein Herr Re-\nferentarius, und wie befindt sie hans Matemoiselle?\n                          Referendarien.\n     Gantz gut, ich danke.\n\n\n                               Scene Vl.\n\n           Magister Buttelbirius, [ de förre ]\n           Magister Buttelbirius ledande sin hund i band, hälsar, sät-\n                 ter sig wid Bordet, sägande långsamt.\n     Jungfru Ingrida, täcktes hon wara af den godheten,\noch transportera mig hit allenast et Halfstop Färsköl, samt\nen skorpa för min hund.\n           [Ingrid går ut och kommer genast in med et Stop Öl och\n                 en skorpa]\n\n                                                                 Buttel-"}, {"pdfPage": 27, "printedPage": null, "text": "23\n\n                         Buttelbirius.\n       Honorem habeo bibendi in sanitatem vestrorum bons-\nrum Dominorum (dricker) hä ä ä — det är certissime et\nbonum cerevisium, det wederqwecker hjärtat, och är en\nhälsedrilck för lungorna. (Han blyter en bit af skorpan och ger\nåt sin hund.)\n\n                        Referendarien.\n     Det war profecto en ganska ful hund, min Herr Ma-\ngister Buttelbirius.\n                         Buttelbirius.\n     Han är likwäl en Canis fidelis atque fidelissimus. Det\när icke ytan man bör rätta sig efter, det är Dignitas in-\nterna & ipsa honestas, som utplåna hwad naturen i det\nutwärtes anseendet förnekar.\n                        Referendarien.\n     Hwad heter Er hund Herr Magister Buttelbirius?\n                         Buttelbirius.\n    Jo, med förlof, han heter Passe, Piger, Niger & Al-\nbus Erinacius, Senex.\n                        Referendarien\n    Det war et ganska höglärdt namn; hwad betyder det\npå Swenska min Herr Magister Buttelbirius.\n                         Buttelbirius.\n     Det är icke min sak, at nu sittja här och explicera\nsådant; hwarföre har icke Herr Referendarien lärt sig Latin.\nHerr Fusswasser, som är en Doctus vir, torde kunna ut-\ntolka det.\n                          Fusswasser.\n    Jah, jah, ich bin en Toctus fir, Aber schall jach\ndervor förschtå hunde latin, dass war gantz impertinent.\n                                                        Er"}, {"pdfPage": 28, "printedPage": null, "text": "24\n\nEr habt fordient ein trumf på de käft vor diesse worte\ndass sage ich und Fusswasser mit.\n\n\n                            Scen. VII.\n\n           Et Håf-Råd i röd Kappa med en liten handlyckta i handen.\n              De öfrige. Så snart Ingrid får se honom, springer hon och\n              tar utaf honom hans Kappa och hänger på wälggen, tar äf-\n              wen lycktan. Håf-Rådet sätter sig wid et särskilt Bord, tar\n              up sin Sjöskums pipa ur fickan och gnider honom.\n\n                           Fusswasser.\n     Undtmykeste diener mein Herr Hoff-Rath.\n                           Håf-Rådet.\n     Go afton, go afton Herr Fusswasser\n                         Referendarien.\n     Hörsammaste tjänare Herr Håf-Råd.\n                           Håf-Rådet.\n     Tack, tack Herr Referendarie.\n                          Buttelbirius.\n     Servus humillimus nec non devotissimus Cultor.\n                            Håf-Rådet\n     Dito, dito, Domino Buttelbirio.\n           (Ingrid kommer in med et Stop Öl och sätter ät Håf-Rådet\n              och niger djupt.)\n\n             Håf-Rådet (klappar henne under hakan.)\n     Hur mår du min pulla lilla, du ser så misslynter uk,\ndu har intet din wanliga glada mine, wi Hof-folk tycka in-\ntet om andra än fryntliga ansigten.\n                                                                Ingrid"}, {"pdfPage": 29, "printedPage": null, "text": "25\n\n                          Ingrid (gråter)\n    Jag fick stryk utaf Frun för det min Fästman war hos\nmig, wälborne Herr Hof-Råd.\n                           Håf-Rådet\n     War han bara hos dig; kom hit med din hand så skal\njag se uti honom hwad Ni gjorde.\n                             Ingrid.\n    Nej, jag har skurit mig i fingret, ja jag skäms wisa\nnäfwen åt wälborne Herrn.\n                           Håf-Rådet.\n     Lät mig då få se i den andra näfwen, det kan wara\nlika mycket.\n                             Ingrid.\n     Nej, min gunstige Herr Håf-Råd, jag har råkat at få\nen sticka i nageln, så fingret har bolnat, annars skulle jag\nwisa Herr Håf-Rådet alt hwad han begår, ty jag är\nintet rädd.\n                           Håf-Rådet.\n    Ha, ha, ha, flicka lilla, du är stucken, så dä har\nbolnat, ha, ha, ha, då har bolnat; ja det tror jag wäl.\nMen se! hwad är det der för et kreatur, (pekar på hunden)\n                       Buttelbirius (stiger op och bockar sig)\n     Det är in se & sua natura en hund reverenter sagt.\n                           Håf-Rådet.\n     Fy, fy, haf ut den der stygga hunden.\n                          Buttelbirius.\n      Jag wil förmoda i kraft af alla regulis humanitatis,\nat jag conjunctim med min hund måtte få lof, at wara\nhär inne, i thy jag betalar för mig och minom hund.\n                                                             Håf-\n\n\n\n\n                                      D"}, {"pdfPage": 30, "printedPage": null, "text": "26\n\n                             Håf-Rådet.\n     Raisonera inte, ut med Er otäcka hund säger jag Er.\n                             Buttelbirius.\n     Men jag ber at man måtte först besinna, hwad den\nlärda Mannen Seneca skrifwer så sinnrikt de Amore & fi-\ndelitate Creaturarum.\n                             Håf-Rådet.\n     Jag ger hin håle alt hwad Seneca skrifwer, han har\nintet skrifwit något om Er otäcka hund, hut ut med honom\nsäger jag Er.\n                             Fusswasser.\n     Wilst du nicht heraus mit dein hund, so schal jach\ndich clabatschiren, so du schal klemme tin hunde-latin.\n(Han springer up, rycker hunden af Buttelbirius och kör ut honom.)\nSo schal man efterkomma de hochfernämes befallningen.\n\n\n                              Scen. VIII.\n\n         Proviantskrifwaren Söderlank, En Hökare. (De förre.)\n\n                        Söderlank (til Ingrid.)\n    Hör Jungfru, känner hon någon Fält-Commissarius,\nsom heter Drommelberg?\n                                Ingrid.\n     Ja, han är wår dageliga gäst.\n                              Söderlank.\n     Har han intet kommit hit ännu?\n                                Ingrid.\n    Nej, men han kommer wäl straxt, om Herrn behagar\nwänta: war så god och sitt ner.\n                                                                Söder-"}, {"pdfPage": 31, "printedPage": null, "text": "27\n\n                             Söderlank.\n    Tack mitt flicka lilla, gif oss et Stop Öl.\n           (Söderlank trallar och sätter sig med Hökaren wid et särskilt\n              bord.)\n\n                          Hökarn (dricker)\n    Skål Skrifware.\n                             Söderlank.\n    Tack Farbror.\n                       Hökarn [ser sig omkring.]\n      Här har jag aldrig warit förr, jag plär mäst gå ut\ntil Linwäfwar-gropen, där har jag mitt eget Stop at dric-\nka ur, med mitt namn inbundit, där går folk som jag\nkänner, de här ansigtena anstå mej inte.\n                            Håf-Rådet.\n    Hwad säger Ni, Karl, wet Ni hwem jag är?\n                              Hökarn.\n    Ja, Karl är jag, men hwem är du?\n                             Söderlank.\n    Tyst, tyst, han är Håf-Råd; Farbror kan bli olycklig.\n                              Hökarn.\n     Är han Håf-Råd, så är jag Hökare; han är ändå\nintet annat än en Skrifware, och jag mocquerar mig öfwer\nalt hwad Skrifware heter; jag kan hwart år köpa en Robe\nåt Hustrun min, som kostar mer, än hela hans årslön\nkanske.\n                             Söderlank.\n    Tyst, tyst, tyst, han är en riker Karl.\n                                                                Hökarn.\n\n\n\n\n                                        D2"}, {"pdfPage": 32, "printedPage": null, "text": "28\n\n                             Hökarn.\n     Ja, är han riker, ja det kan så wara, det är det enda\njag sätter wärde på, men är han wärkelig Håf-Råd?\n                            Söderlank.\n      Nej, han är endast caracteriserad. Han har eljest en\nliten Hofsysla.\n                             Hökarn.\n     Nå, hwarför ser han då så dryger ut?\n                            Söderlank.\n     Jo, jo, för det lyckan har sparkat fram honom — och\nännu så mycket mera framfuss är han, för det han fått\nen titel af en tjänst, den han aldrig skulle kunna förestå.\n                             Hökarn.\n      Han måste så mycket mera skämmas: intet må han\ntro, at han får respect för caritören: det kom en pojke til\nmig härom dagen och wille köpa et ljus för en förgylter\nslant, men han fick ändå icke tjockare ljus, än jag wanli-\ngen plär sälja för en styfwer, om han wore aldrig så\nmöglig.\n                            Söderlank.\n     Drick Farbror.\n                             Hökarn.\n     Ja, då ska du sjunga min wisa.\n                            Söderlank.\n     Ja, ja.\n                          Hökarn [dricker och Söderlank sjunger.]\n                    Bacchus är redlig,\n                    Torstig och fredlig,\n                    Leswer så makligt och fettmar i söl;\n\n                                                           Röd"}, {"pdfPage": 33, "printedPage": null, "text": "29\n\n                     Röd uti synen\n                     Och ögonbrynen\n                Blötas och frodas af swett och af Öl.\n                     Bachus är lustig,\n                     Fucktig och mustig,\n                Röker sin Rulltobak, grinar åt Soln.\n                     Han sig förlustar\n                     Stånkar och pustar,\n                Til dess han hwimlar och tumlar af stoln.\n\n                           Håf-Rådet.\n     Sådant kallar jag för liderliga Wisor, det är skam\naf Er, som är en ungdom, at så skråla i gammalt förnämt\nfolks presence.\n                            Söderlank.\n     På Ölställen ha wi lika rang, och här dricker jag så\nwäl som Håf-Rådet, och ger aldrig et ord efter.\n                           Håf-Rådet.\n     Hwad är Ni för slag?\n                            Söderlank.\n     Jag är Proviantskrifware.\n                           Håf-Rådet.\n     Ha, ha, ha, Proviantskrifware! jag tror Ni bättre\nskulle tjäna til Källarskrifware.\n\n\n                            Scene IX.\n\n                     Drommelberg. [ De öfrige. ]\n\n                         Drommelberg.\n     Go afton, go afton gode Herrar. [ Til Proviantskrifwaren. ]\nSe, har du länge wäntat på mig Bror Söderlank?\n                                                            Söder-\n\n\n\n\n                                         D3"}, {"pdfPage": 34, "printedPage": null, "text": "30\n\n                          Söderlank.\n    Nej, bara en liten stund, jag har intet hunnit, at dric-\nka mer, än twå gångor.\n                     Drommelberg (slår sin hatt i bordet och\n                                      sätter sig.)\n      Den wäntar, icke för länge, som wäntar efter något\ngodt. Du skal tro, en Parentation är inte så snart skrif-\nwen: jag har setat alt sen kl. 6 i mårses tils nu och ar-\nbetat med den flit, at jag knapt hunnit taga mig öfwer\n7 eller 8 supar, så rasande brottom har jag haft.\n                          Håf-Rådet.\n     Har Ni skrifwit en Parentation Herr Fält-Commissarius?\n                        Drommelberg.\n    Ja, Herr Håf-Råd, rörd i mitt innersta öfwer min\nmäns den olyckliga Finkels oförmodade dödsfall, har jag\nhonom til ära och hogkomst i hast sammansatt et Tal i\nbunden stil, hwilket jag wil hålla härstädes i afton.\n                          Håf-Rådet.\n     Är Ni så snäll i Poësin Herr Drommelberg?\n                        Drommelberg.\n      Herr Fält-Commissarie, om Herr Håf-Rådet behagar,\njag är så man om min Caracter, som en an om sin, och\nhwad för öfrigt Poësin widkommer, så är det intet mera\nswårt för mig, at skrifwa vers, än för en tupp, at gala;\nty det är mig medfödt. Jag har skrifwit många wackra Skrif-\nter, som til exempel, Et Ode öfwe Rung Abasweri Fawo-\nrit, som omsider kom, at stå på intet och titta genom sin lycka:\nElegie öfwer Rung Fjollner, som föll ner i et Mjödkar\noch drunknade, då han skulle besöka sin Maitresse på et\n                                                        winds-"}, {"pdfPage": 35, "printedPage": null, "text": "31\n\nwindsloft: Grifte - Runa öfwer tjocka Repslagaren,\nsom på femtonhundrade talet sprack af dumhet och gam-\nmalt Franskt: (spottar) Ingrid gif mig et Stop Öl. Wi-\ndare En Opera i 36 Acter om Jonas i Hwalfiskens\nbuk: Et exempel för alt hwad Opera heter; Musiquen är\nunder Composition hos Stads-Musicanten Mowitz. (Herr\nHåf Råd jaq har den äran.) Ytterligare En Poeme Epique,\nsom jag författade i Benswarfwars Trägård under namn\naf Hallon-Öleade. (Gutår Herr Referendarie, Mamsells skål\ninclusive:) Skalde-Bref til Auctoren af Casper och Doro-\nthea, med behörig näpst, för det han wågat i denna sin\nusla Parodie personalisera den respectabla Watronan Ma-\ndam Gram på Djurgåln. (Skål Herr Doctor Fotwattn.)\nItem til samma Satyriska Autor en Apostille i anseende\ntil Prologuen af Casper och Dorothea, som är så skrifwen,\nat Fruntimren wid wissa infall deruti, måste hålla skratten\ntilbaka, hwilket kan förordsaka dem swåra påfölgder: Me-\nmorial i Heroisk stil til wissa unga Herrar, som med\nkäppstötar, vanständigt buller, hjärtfrätande skratt och obe-\nhörig hwisling, icke allenast hindra sina medåskådare, utan\näfwen förolämpa Acteurerne wid Theatren i Kongl. Hum-\nblegården; och utom alt detta 999 Brudskrifter, 684 Graf-\nskrifter, förutan 1000 tals Epigrammer, Madrigaler och små\nInfall, och sluteligen den Parentation, som jag nyss för-\nfattadt öfwer Finkel.\n                         Håf-Rådet.\n      Jag må tilstå, at Herr Fält-Commissarien måste wara\nen flitig man, som hunnit med så mycket arbete.\n                       Drommelberg.\n     Å Herr Hof- Råd! alt sådant är en bagatelle för mig:\njag är i stånd at skrifwa 300:de versar på en förmiddag\n                                                       öfwer"}, {"pdfPage": 36, "printedPage": null, "text": "32\n\nöfwer hwad ämne som behagas. Hör Ingrid, bed Syster\nCicilia komma in. ( Ingrid går.)\n\n\n                             Scene X.\n\n                        Fru Cicilia. Ingrid. (De förre.)\n\n                         Drommelberg.\n     God afton Syster Cicilia! Ni wet, at den där namn-\nkunniga Advocaten lilla Herman Finkel är död; Och\nsom jag anser Er Klubb för den förnämsta och lärdaste i\nhela Staden, så har jag beslutit, at härstädes i afton hålla\nen Parentations-Act öfwer denne min afledne Wän.\n                              Cicilia.\n      Det är Er wärdigt Bror Drommelberg, Ni wet, at\nrätt hedra wänskapen.\n                         Drommelberg.\n      Men Syster! wi måtte anställa detta med all Ceremo-\nnie; Jag bör wara swart, låna mig Er Saloppe.\n                              Cicilia.\n     Min Salopp? Twy mej jag det gör, han är wäl\ndyrare än så, wil Ni ha min swarta Sattins Kjol skal\nNi få.\n                         Drommelberg.\n     Ja men, det kan wara lika så godt det, så år jag\ntäckt öfwer alt. Hör mina wänner allesamman, gå in i\nSyster Cicilias Säng-Kammare; medan hon, jag och In-\ngrid ställer alt ting i ordning härute, så skola wi sedermera\nsamfält gå i prosession hit ut i Parentations Salen. (De gå.)\n(Täcket faller.)\n                                                           Scene."}, {"pdfPage": 37, "printedPage": null, "text": "33\n\n\n\n                    Scene XI.\n\n [Theatren är Fru Cecilias Öl-Sal, alla Borden äro uttagne,\n     midt på golfwet står allenast et litet fyrkantigt bord, öfwerhölgt\n     med et swart kläde, som räcker ned til golfwet; i Fonden af\n     Theatren, bak för Bordet, står en trekantig Sten-Pyramid, upsatt\n     på en opp och ner stjälpt Tunna, på spetsen af berörde Py-\n     ramid hänger Finkels röda Surtout, Rosette -Peruque, Car-\n     pus och wärja. Framför Bordet står en Länstol för Paren-\n     tatorn, och på ömse sidor stolar för åhörarena i halfcirkel\n     stälde; på det swarta Bordet stå åtskillige Trästop i stor\n     Cirkel opp och ner stjälpte, i hwilken krets sedermera Pyrami-\n     den kommer at ställas.]\n\n                  Processionen\n     Sker ganska långsamt 2:ne hwarf omkring Bordet och Pyrami-\nden, under afspelande af en sorgelig Marche, i följande ordning.\n     Ingrid främst med et ljus i hwardera handen. Fyra Gåssar.\nParentatorn med Cicilias Kjortel öfwer axlarne. Cicilia. Håf-\nRådet. Långa Referendarien. Fusswasser. Buttelbirius. Hö-\nkaren. Söderlank.\n     Sedan Processionen är slutad, börjas Chorus af Gåssarne.\n\n             Wår Marcus Finkel Advocat,\n             Gör Bacchus sjelf i döden flat.\n             Som Hjälte han til grafwen gick,\n             Directe från Krogen,\n             Kom döden och togen,\n             I bästa skick.\n             Hans lefnad mellan Ölstop skred,\n             Han Rusets plåga tåligt led,\n             Han war m härdad Bacchi dräng,\n             Som myggor ej silde,\n             I Rennsten han hwilde\n             Liksom i säng.\n\n                                                        Wår\n\n\n\n\n                                E"}, {"pdfPage": 38, "printedPage": null, "text": "34\n\n                       Wår Finkels Bild med bästa färg,\n                       Skal målas utaf Drommelberg,\n                       At bli et werldens Monument;\n                       Och gömmas åt tiden.\n                       Res up Pyramiden,\n                       Som han förtjänt.\n               Då hjälpas de åt, at lysta Pyramiden up på swarta Bordet,\n         och ställa honom midt i Cirkelen af Ölstopen.\n\n                           Drommelberg.\n    Til denna solenna Act har jag äfwen författadt någon\nCantata på samma ton, som wisan öfwer Fader Movitz\nLungsot. Ingrid lilla, du har en skär röst, wil icke du\nwara så god och discanta desse versar.\n                            Ingrid (sjunger)\n                   Liksom en eld af glödgadt bränwin drifwer,\n                   Drifwer i högd, men slocknar ganska snart,\n                   Och med sin glants et mänsko-lif beskrifwer,\n                   Som hastigt qwäfs uti sin fart.\n                   Så ock wår Finkel — — — — hans lif och hans skugga,\n                   — — — — — — kan afund ej tugga.\n                   Han har sin möda ej i werlden spart.\n                                 *      *\n                                 *\n                   Han war Honette, han torstig war och trogen,\n                   Fattig, men fri, och altid oförskräckt,\n                   Utan facon han gick från krog på krogen,\n                   Wärdigt en Son af Klunkars Slägt,\n                   Finkel! ach! Finkel! så har du förswunnit,\n                   — — — — Ditt Stop är utrunnit,\n                   Barbro har kändt din sista Andedrägt.\n               Drommelberg sätter sig fram för Bordet. De öfrige på sina\n         Stolar. Drommelberg tar opp sin Parentation ur fickan, hostar, spot-\n         tar , snyter sig, och i det han emottager et Stop med dricka af In-\n         grid, börjar således:\n\n                                                                 Gut-"}, {"pdfPage": 39, "printedPage": null, "text": "35\n\n                       Drommelberg.\n     Guttår, (dricker) Er Tjenare, I Klubbens wärda Fäder,\nJag först min sorgsna blod med någon wätska späder,\nAt han må blifwa tunn och lätt och löpa qwikt,\nWid Finkels sanna lof i denna Skalde-dikt,\nDu Bacchus, Källrars Gud och Klubbars lmperator,\nSom nästan har et slott på hwar af Stockholms gator,\nSom ropar: Sup min Son! så är din werld ej trång;\nStyr du min Andas drift! Späd olja i min sång!\nApollo! på din hjelp jag wille också mana,\nMen efter nyckterhet är jämt och samt din wana,\nSå gagnar mig ej stort den kraft jag af dig får,\nÖl min Apollo är! til saken nu — — Guttår, (dricker)\nDock först och innan jag, min Finkels werld förtäljer,\nHur dråpligt han har lyst, bland Ölstop och Bouteljer,\nJag något nämna bör om Hjältens Origine,\nSom sörjes nu af oss och af sitt enda swin.\nHans Farfars Farfars Far, war Fjälsman uppå Åland,\nBlef sedan flyttad bort til Länsman uti Småland,\nHan hette Jesper Rlunk och ur så wärdig Stam,\nHar Herman Finkel trädt på werldens bane fram.\nRlunk är en talrik Slägt, af Rlunkar ha wi många,\nEn Rlunk Fältwäbel war och bodde uti Spånga,\nOch just den samme Rlunk, en skarp rödfrasig Kar,\nHan war wår Döde Wäns den käcka Finkels Far;\nEn grym Manhaftig Buss, som stod i alla wäder,\nMed Handskar, Böxor, Wäst, alt utaf Elgshuds läder:\nGif Ungen, ropte han, i Bränwin doppadt bröd,\nDet styrker Pojkens Mod och hämmar öfwerflöd;\nSå wäxte lilla Rlunk och war en Godagssälle,\nOch söp så godt som trots båd Jöns och Matts och Pälle,\nMen läste mellanåt, hälst Lagen Excellent,\nTil dess han wärdig fants, at göras til Student.\nPå hans Studentwäg ej så stort af wärde mötte,\n                                                      Sin\n\n\n\n\n                                   E2"}, {"pdfPage": 40, "printedPage": null, "text": "36\n\n     Sin Bok han då och då, i Öl och Bränwin blötte,\n     Och som det Namnet Rlunk ej tycktes klinga nog,\n     Han ganska wäl betänkt, sig Namn af Finkel tog.\n     Som Finkel trädde han in i den stora werlden,\n     Som Finkel gick han bott i den Krypinska färden,\n     Som Finkel steg han opp först til Auscultant,\n     Som Finkel aldrig han i werlden längre hant;\n     I stöd af sin Moral, han sig twå Walspråk sökte,\n     Som altid hans beröm båd qwäll och morgon ökte,\n     Först: Morgonrodnans sten är Advocatens wän,\n     Sen: Aldrig skal en tår i Stopet bli igän.\n     I Källare Palats man aldrig såg wår Finkel,\n     Han wid et En-stop satt, förnöjd uti en winkel.\n     Och då han där i rus på glatta golfwet låg,\n     Man honom lika fullt med wördsamt öga såg.\n     Den som wår Finkel lik i werlden så arbetar,\n     Han ock mot dödens udd ej mycket länge stretar,\n     Och fast i unga år han stupar i sin sauce,\n     Hans minne med hans lif ej lika snart förgås,\n     Hwad är då menskjans lif? — — — lät se — — — jo på min ära,\n     Går det i liknelse et Ölstop mycket nära,\n     Som räcker ganska kort, man sätter det til mund,\n     Tre, fyra klunkar gå, och det är tömt på stund;\n     Dock lika mycket är hur länge lifwet warar,\n     Blott wåra krafters bruk jämt opp mot tiden swarar,\n     Har man ej spädt sin blod, har man ej druckit stort,\n     Så har på werldens rymd, man föga dater gjordt;\n     En torr och törstlös själ, hwad kan wäl den bestrida?\n                        Fusswasser.\n     Wohl gefraget, wohl gefraget; Tach mich knäffel wenn\njach icke annamme fymf undt sex sauffen, ich bin nicht Ca-\npabel ein ader zu öffnen.\n                                                    Drom-"}, {"pdfPage": 41, "printedPage": null, "text": "37\n\n                        Drommelberg.\n      Hwad kan wäl, säger jag, en torstlös själ bestrida,\nSjelf trumpen kan han ej sin nästas nöjen lida,\nMen den, som super bra, och wet at ta til lifs,\nOm honom tryter alt, han lika muntert trifs.\n                           Fusswasser\n     Schent! Schent! man per altit supe praff, altrich ware\nnichter; hwarfer? ti på nichter mage kan man flux pliffe\nimpesteredt.\n                        Drommelberg.\n      Slikt Bacchi Axiom wår wärda Finkel miste,\nHos honom aldrig torst och ej Courage briste,\nSå liten som hans kropp, så stor war dock hans själ,\nAt han decisum gaf wid alla Ölstops gräl,\nJag glömmer ej en qwäll, hwad hände på Cardusen,\nSatt Finkel trygg, och tyst, masquerad i Carpusen;\nSå satt der ock en Man, en Smed til profession,\nOch talte ganska stort om Calmar Union.\nHan sad’, ifrån den tid, kan Swerge räkna Coursen,\nÄnnu satt Finkel tyst och smälde åt discoursen!\nMen rätt som bäst det war, han Stopet från sig sköt,\nSteg opp och ropte högt: Ni talar som et Nöt.\nFlink flarum floribus här blef et fasligt buller,\nEn Smed han tål ej stort och minst när han är fuller;\nMen Finkel, o-försagd, han strök med hjälte-mine\nDen goda Mäster-smed midt i Physionomien.\nDet war et gruflig slag så Stopet braka sönder:\nGå skal du tala nöt när du är ibland bönder,\nMen ej bland höglärdt folk; straxt Smeden modfält war,\nOch hela Klubben skrek, at Finkel han war Kar.\nSen söps förskräckligt Öl i kraft af hjälte-lagen,\nSå Finkel somna af och satt til andra dagen.\n                          Fusswasser.\n     Til andre tagen! dass war carnallieust gemacht, dat\nwar, at storme krimt på hälse und krafter.\n                                                            Drom-"}, {"pdfPage": 42, "printedPage": null, "text": "38\n\n                       Drommelberg.\nMen det är icke nog af Finkels wett och mod,\nHan ofta wedergält sin djärfhet med sitt blod,\nEn gång det tilbar sig, på Krogen Röda Rnuten,\nHan för en Lag-question slog Krögarn uppå truten,\nMen fick et slag igen så Skinn-Carpusen sprack;\nDer låg han stel och blek liksom en Palsternack.\nMen mon på minsta sätt han derför tappa modet?\nNej, som en Hercules han wred sig uti blodet,\nOch sade, om jag dör så rista på min Graf,\nHär har en Advocat lagt ner sin Wandrings-Staf:\nI botten ärlig Karl, men hätskt emot Filuris,\nSom lefwer utaf Öl, och dödt för Corpus juris.\n                        Buttelbirius.\n     Domine Parentator, det ordet Filuris war salva ve-\nnia en nästan stark licentia Poëtica.\n                       Drommelberg.\n     Det förstår Ni intet, jag såsom gammal Auctor har\ntilwunnit mig Parnassens privilegium exclusivum på wissa\nord, men jag får sjelf tilsmida mig rim när de brista.\n                         Fusswasser.\n     Och jah! och jah! den Herr Commissarius ist priffilekert.\n                 Drommelberg (Continuerar.)\n     — — — — Jag sade hätskt emot Filuris,\nSom lefwat utaf Öl, och dödt för Corpus juris;\nSå tapper som han war så war han äfwen snäll;\nAt supa ut en sup, at skrifwa en Libell,\nWar honom lika lätt för sina principaler.\nHan wid en Domstol stod liksom ibland Pocaler.\nOch at han stundom föll och något snesprång tog,\nWar mer af distraction, än wärkan af en Krog.\nDen nio Balkar bär uti sin trånga skalla,\n                                                      Kan"}, {"pdfPage": 43, "printedPage": null, "text": "39\n\nKan snarare af dem, än nio supar falla;\nDessutom den som ej i dryckom duger stort,\nHan ingen Lagkarl är, det har jag sjelf försport.\nSå war wår Finkel stor uti Processualier;\nTil strupen wid och stor; men uppå Victualier,\nEn ganska liten man, En fjärndels lappsik war,\nFör honom föda nog, snart sagt i åtta dar.\nGuttår! på många sätt war Finkel stor i tiden,\nHan war som Bacchus sjelf på alla Krogar liden;\nHwar hälst han trädde in han glädjen med sig tog,\nTy knapt man honom såg, förrn man af hjertat log.\nOm Naso lefde än det wist hans ensak blifwit,\nDen Näsan skrifwa om Naturen Finkel gifwit,\nHon war så stor och skön och gaf det bästa hopp,\nAt hwar han trädde in han lyste rummet opp.\nApelles Pensel knapt dess afbild kunnat måla,\nTy hwar fins färgor til som så i klarhet pråla?\nJag nämner blott en knöl, han war så klar och blå,\nLiksom en Lazur sten; förutan många små,\nSom utstack här och der, och lyste som Saphirer,\nIbland couleur de feu af många slags brochurer.\n                   Buttelbirius (stiger opp.)\nPer Jovem! jag rörs af denna målnings Sublimitet,\n     Längst in i min själs simplicitet,\n     Och måste bekänna ex corde meo,\nAt jag är mot Herrn, som en katt mot et Leo;\nHwad är den fägring wi i werldene njuta,\nOch bäre så stålt på detta lifwets skuta?\n     Hon lyser som i glas et aqua vita,\n     Men lika så lätt är hon perdita.\n                      O! du Formositas.\nDu wäcker tam gaudium quam calamitas!\n     Jag gråter öfwer din kosteliga näsa\n     Som så stolt i werldena månde gäsa,\n                                                     Men"}, {"pdfPage": 44, "printedPage": null, "text": "40\n\nMen omsider krupit neder bland dem,\nSom blifwa til stoft och aska tandem,\n     Nu kan man clarissime se,\nSå swekfult är werldsens wäsende.\n\n\n                                    Scene XII.\n\n                      Secter Gasp med hatten på hufwud.\n              Go afton, Fru Cicilia. Et stop Öl om Er behagar.\n\n                                      Cicilia.\n      Nej, jag behagar inte något Öl.\n\n                                       Gasp.\n      Jag behagar sjelf, bär hit.\n                                      Cicilia.\n      Nej, denna Klubben är endast för gammalt folk och inte för några\nGaspar; jag har inte Öl åt Er, men om Ni behagar sitta ner och\nhöra på Parentationen, det kan jag inte neka.\n\n                                       Gasp.\n      Hwem är den öfwer?\n                                      Cicilia.\n      Öfwer Finkel om Er behagar, han som want Processen mot Er\nför Fiskblötar Mor.\n                                       Gasp.\n      Parentation öfwer det kreaturet, som dog på Krypin! ha, ha, ha,\nha, ja det är wärdigt at hålla honom här. Hwilken är Parentatorn?\n\n                                      Cicilia.\n      Fält-Commissarien Drommelberg om Er behagar.\n\n                                       Gasp.\n      Ja, som Cadavret war så är Parentatorn, ha, ha, ha, de äro\nbägge wärda at sitta uti taket på et Apotek.\n      Drommelberg springer til och slår Gasp en örfil. I det sam-\n            ma hwälfwer Finkel, som sitter under bordet i spökelse gestalt,\n            bordet öfwer ända tillika med hela Pyramiden, och stiger fram;\n            då de andre se honom, springa de ut på åtskilliga sidor; Fin-\n            kel skrider fram til dem som slåss, och tar Gasp i Näsan och\n            leder honom ut; han skriker. Drommelberg sätter til fötters\n            och stupar öfwer Pyramiden. (Täcket faller.)"}]}
;
